-- Mood Wear — 802244 Digital Database Final Project
CREATE DATABASE IF NOT EXISTS moodwear CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE moodwear;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS favorites;
DROP TABLE IF EXISTS cart_items;
DROP TABLE IF EXISTS order_items;
DROP TABLE IF EXISTS orders;
DROP TABLE IF EXISTS users;
DROP TABLE IF EXISTS products;
CREATE TABLE products (id INT PRIMARY KEY, name VARCHAR(255) NOT NULL, price INT NOT NULL, category VARCHAR(50), stock INT, img VARCHAR(255) DEFAULT '', vgroup VARCHAR(64) DEFAULT '', vname VARCHAR(128) DEFAULT '', vorder INT DEFAULT 0);
CREATE TABLE users (id INT PRIMARY KEY, username VARCHAR(100) NOT NULL, email VARCHAR(150) NOT NULL UNIQUE, phone VARCHAR(30), password_hash VARCHAR(64) NOT NULL);
CREATE TABLE orders (id INT PRIMARY KEY, user_id INT, address VARCHAR(255) NOT NULL, total INT NOT NULL, created_at DATETIME, FOREIGN KEY (user_id) REFERENCES users(id));
CREATE TABLE order_items (id INT PRIMARY KEY, order_id INT NOT NULL, product_id INT NOT NULL, quantity INT NOT NULL, size VARCHAR(20), color VARCHAR(64), unit_price INT NOT NULL, FOREIGN KEY (order_id) REFERENCES orders(id), FOREIGN KEY (product_id) REFERENCES products(id));
CREATE TABLE cart_items (id INT PRIMARY KEY, user_id INT NOT NULL, product_id INT NOT NULL, quantity INT DEFAULT 1, size VARCHAR(20) DEFAULT "M", color VARCHAR(64) DEFAULT "", UNIQUE (user_id, product_id, size, color), FOREIGN KEY (user_id) REFERENCES users(id), FOREIGN KEY (product_id) REFERENCES products(id));
CREATE TABLE favorites (user_id INT NOT NULL, product_id INT NOT NULL, created_at DATETIME, PRIMARY KEY (user_id, product_id), FOREIGN KEY (user_id) REFERENCES users(id), FOREIGN KEY (product_id) REFERENCES products(id));
SET FOREIGN_KEY_CHECKS=1;

-- ══ Views สำหรับอ่านข้อมูลแบบเห็นชื่อ (ไม่ต้องจำรหัส) ══
CREATE OR REPLACE VIEW v_orders AS
SELECT o.id, o.user_id, u.username AS user_name, o.address, o.total, o.created_at
FROM orders o LEFT JOIN users u ON u.id = o.user_id;

CREATE OR REPLACE VIEW v_order_items AS
SELECT oi.id, oi.order_id, u.username AS user_name, oi.product_id, p.name AS product_name,
       oi.quantity, oi.size, oi.color, oi.unit_price
FROM order_items oi
LEFT JOIN orders o ON o.id = oi.order_id
LEFT JOIN users u ON u.id = o.user_id
LEFT JOIN products p ON p.id = oi.product_id;

CREATE OR REPLACE VIEW v_cart_items AS
SELECT ci.id, ci.user_id, u.username AS user_name, ci.product_id, p.name AS product_name,
       ci.quantity, ci.size, ci.color
FROM cart_items ci
LEFT JOIN users u ON u.id = ci.user_id
LEFT JOIN products p ON p.id = ci.product_id;

CREATE OR REPLACE VIEW v_favorites AS
SELECT f.user_id, u.username AS user_name, f.product_id, p.name AS product_name, f.created_at
FROM favorites f
LEFT JOIN users u ON u.id = f.user_id
LEFT JOIN products p ON p.id = f.product_id;
